import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"JustEnoughAccuracy","description":"","frontmatter":{"title":"JustEnoughAccuracy","order":10},"headers":[],"relativePath":"zh/mods/just-enough-accuracy.md","filePath":"zh/mods/just-enough-accuracy.md","lastUpdated":1786943111000}'),d={name:"zh/mods/just-enough-accuracy.md"};function n(s,t,c,l,i,u){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="justenoughaccuracy" tabindex="-1">JustEnoughAccuracy <a class="header-anchor" href="#justenoughaccuracy" aria-label="Permalink to &quot;JustEnoughAccuracy&quot;">​</a></h1><blockquote><p>新的<strong>角度级精度判定</strong>（JEA）——读取与官方判定相同的命中数据，但用自己固定的赋分表评分，与原判定<strong>共存且互不影响</strong>。支持查看判定细节并导出游玩数据。</p><p>项目地址：<a href="https://github.com/adofaiex/JustEnoughAccuracy" target="_blank" rel="noreferrer">https://github.com/adofaiex/JustEnoughAccuracy</a></p></blockquote><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ol><li><strong>新的 <code>JEA</code> 精度</strong> —— 独立于官方判定的附加精度</li><li><strong>详细结果查看器</strong> —— 每关结束后可打开窗口，查看逐块细节，支持搜索与滚动浏览整个会话</li><li><strong>导出与分享</strong> —— 将会话导出为 <code>.yaml</code> 文件或交互式 <code>.html</code> 图表</li></ol><h2 id="判定机制" tabindex="-1">判定机制 <a class="header-anchor" href="#判定机制" aria-label="Permalink to &quot;判定机制&quot;">​</a></h2><p>JEA 是固定的<strong>赋分制</strong>判定：</p><ul><li>每块的原始<strong>角度偏差先归一化到参考 BPM</strong>（<code>deviation × 100 / BPM</code>），因此任意谱面上相同的毫秒级时间误差得分一致</li><li>归一化偏差按<strong>固定分档表</strong>评分，相邻锚点之间<strong>线性插值</strong>——所以 95、97、98.4 等任意分值都可达，而不只是锚点值</li></ul><table tabindex="0"><thead><tr><th>归一化偏差</th><th>得分</th></tr></thead><tbody><tr><td>≤ 1.7°</td><td>100</td></tr><tr><td>2.0°</td><td>96</td></tr><tr><td>2.4°</td><td>92</td></tr><tr><td>2.8°</td><td>88</td></tr><tr><td>3.2°</td><td>84</td></tr><tr><td>3.6°</td><td>80</td></tr><tr><td>4.0°</td><td>75</td></tr><tr><td>4.5°</td><td>70</td></tr><tr><td>5.0°</td><td>62</td></tr><tr><td>5.5°</td><td>54</td></tr><tr><td>6.0°</td><td>46</td></tr><tr><td>6.6°</td><td>36</td></tr><tr><td>7.2°</td><td>26</td></tr><tr><td>8.0°</td><td>15</td></tr><tr><td>&gt; 8.0°</td><td>0</td></tr></tbody></table><h3 id="其它规则" tabindex="-1">其它规则 <a class="header-anchor" href="#其它规则" aria-label="Permalink to &quot;其它规则&quot;">​</a></h3><ul><li><strong>连击</strong>：连续得分 ≥ 50 的块构成连击。连击仅用于显示，<strong>不参与乘法</strong>，因此 JEA 精度上限为 100%</li><li><strong>空按容忍</strong>：镜像官方 <code>consecutiveMultipressCounter &gt; 8</code> 规则——前 8 次连续空按被原谅，之后每次空按扣 -100 并重置连击</li><li><strong>漏块 / 过载</strong>：每个失败块记 -100</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>JEA Acc = TotalScore / (Tiles × 100)   （最多 4 位小数）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="导出" tabindex="-1">导出 <a class="header-anchor" href="#导出" aria-label="Permalink to &quot;导出&quot;">​</a></h2><p>导出文件写入 <code>&lt;mod 目录&gt;/reports</code>。</p><h2 id="要求" tabindex="-1">要求 <a class="header-anchor" href="#要求" aria-label="Permalink to &quot;要求&quot;">​</a></h2><ul><li>支持加载器：UnityModManager、MelonLoader、BepInEx</li><li>游戏版本：≥ 3.1.0</li></ul><h2 id="联动" tabindex="-1">联动 <a class="header-anchor" href="#联动" aria-label="Permalink to &quot;联动&quot;">​</a></h2><p>安装 <a href="./not-enough-accuracy">NotEnoughAccuracy</a>（NEA）后，其数据也会在详细查看器与导出中显示。</p>',17)])])}const p=a(d,[["render",n]]);export{g as __pageData,p as default};
